patch.rtl/priority_encoder.sv:
@@ -3,6 +3,8 @@ module priority_encoder_8x3 (
     output reg  [2:0] out         // 3 output lines
 );

+int msb_pos;
+
 always @(*) begin
     if (in[7])
         out = 3'b111;
@@ -23,11 +25,26 @@ always @(*) begin
     else
         out = 3'b000; // Default case when no inputs are active

-    if (in != 0)
-        assert ($clog2(in) - 1 == out) else $error("Priority encoder failed because in = 0x%h $clog2(in) - 1 =0x%h and out = =0x%h", in, $clog2(in) - 1, out);
-    else 
-        assert ($clog2(in) == out) else $error("Priority encoder failed because in = 0x%h $clog2(in) =0x%h and out = =0x%h", in, $clog2(in), out);

+    // if (in == 8'd0 || in == 8'b1)
+    //     assert (out == 3'd0) else $error("Priority encoder failed: in=%b, out=%0d, expect=3'd0", in, out);
+    // else if (in == 8'd2) 
+    //     assert (out == 3'd1) else $error("Priority encoder failed: in=%b, out=%0d, expect=3'd1", in, out);
+    // else
+    //     assert (out == $clog2(in) - 1) else $error("Priority encoder failed: in=%b, out=%0d, expect=%0d", in, out, $clog2(in) - 1);
+
+end
+
+always @(out) begin
+    msb_pos = -1;
+    for (int i = 7; i >= 0; i--) begin
+        if (in[i]) begin
+            msb_pos = i;
+            break;
+        end
+    end
+    assert (out == (msb_pos == -1 ? 3'd0 : msb_pos)) 
+        else $error("Priority encoder failed: in=%b, expected=%0d, out=%0d", in, msb_pos, out);
 end

 endmodule
